import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"English Diagnostic: Four-skill Baseline and Transfer Record","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/english-diagnostic.en.md","filePath":"public/downloads/worksheets/english-diagnostic.en.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/english-diagnostic.en.md"};function d(o,e,s,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="english-diagnostic-four-skill-baseline-and-transfer-record" tabindex="-1">English Diagnostic: Four-skill Baseline and Transfer Record <a class="header-anchor" href="#english-diagnostic-four-skill-baseline-and-transfer-record" aria-label="Permalink to &quot;English Diagnostic: Four-skill Baseline and Transfer Record&quot;">​</a></h1><p>This is the full four-skill diagnostic worksheet, not the five-minute starting task or an exam that pins a person to A1-C2. To begin with one small action, use the <a href="https://byoungd.github.io/up/en/topics/english-diagnostic" target="_blank" rel="noreferrer">English Diagnostic hub</a> for a five-minute baseline in one skill. For a full diagnostic, choose one real topic and complete listening, reading, speaking, and writing first versions under comparable time and explicit limits, then retest a parallel task after seven days and one real delivery after thirty days.</p><p>Copy this card into a private note. Do not include passwords, customer records, identity documents, medical privacy, unauthorised third-party material, or exam content that may not be recorded.</p><h2 id="_1-define-the-diagnostic-boundary" tabindex="-1">1. Define the Diagnostic Boundary <a class="header-anchor" href="#_1-define-the-diagnostic-boundary" aria-label="Permalink to &quot;1. Define the Diagnostic Boundary&quot;">​</a></h2><h3 id="english-diagnostic-yyyy-mm-dd" tabindex="-1">English Diagnostic - YYYY-MM-DD <a class="header-anchor" href="#english-diagnostic-yyyy-mm-dd" aria-label="Permalink to &quot;English Diagnostic - YYYY-MM-DD&quot;">​</a></h3><p>Real context: work / study / job search / life / other<br> Real topic:<br> Audience or conversation partner:<br> Smallest shared delivery across four skills:<br> Start/end dates:<br> Material, version, and source:<br> Shared limits (time, device, environment):<br> Permitted dictionary / captions / translation / search / AI / human help:<br> Privacy, copyright, exam, and expert-responsibility boundary:<br> Day-7 parallel-task date:<br> Day-30 retest date:<br> Week-12 real-task date:</p><p>The four tasks need not use identical material. Keep topic, difficulty, time, and acceptance standards comparable enough to interpret. For a real role, do not let one overall level replace the language actions in the job description.</p><h2 id="_2-four-first-version-tasks" tabindex="-1">2. Four First-version Tasks <a class="header-anchor" href="#_2-four-first-version-tasks" aria-label="Permalink to &quot;2. Four First-version Tasks&quot;">​</a></h2><p>Complete the first version without looking things up or asking AI to answer or rewrite. Finish first, then mark where support was needed.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Suggested first version</th><th>Minimum delivery</th></tr></thead><tbody><tr><td>Listening</td><td>Hear a real 2-4 minute clip once</td><td>Main point, three certain details, responsibility/next step, and 60-second retelling</td></tr><tr><td>Reading</td><td>Read a real 600-1000-word text</td><td>Five-line main thread, one evidence location, and one challenge or unknown</td></tr><tr><td>Speaking</td><td>Record an unscripted two-minute explanation, experience, or process</td><td>Listener can retell purpose, key facts, and next step</td></tr><tr><td>Writing</td><td>Write a 180-250-word email, explanation, or argument in 20 minutes</td><td>Reader knows conclusion, support, limits, and action</td></tr></tbody></table><p>Do not flatten genuine differences to make the four skills look equal. The diagnostic should show where ability works, not manufacture a flattering average.</p><h2 id="_2a-record-collaboration-dimensions-when-needed" tabindex="-1">2A. Record Collaboration Dimensions When Needed <a class="header-anchor" href="#_2a-record-collaboration-dimensions-when-needed" aria-label="Permalink to &quot;2A. Record Collaboration Dimensions When Needed&quot;">​</a></h2><p>Add the tasks below when your goal includes remote collaboration, customer communication, classroom discussion, or family learning. They are not new levels and do not need to be tested every time; keep evidence when they affect a real outcome.</p><table tabindex="0"><thead><tr><th>Task dimension</th><th>10–15 minute sample</th><th>Evidence location and result</th></tr></thead><tbody><tr><td>Mediation and retelling</td><td>Read two short texts with different positions and explain each claim, difference, and unknown</td><td>Listener distinguishes the source, your retelling, and your inference;</td></tr><tr><td>Online interaction</td><td>Write one progress update, one blocker, and the next step so the other person can continue without a meeting</td><td>The other person knows the owner, timing, and missing information;</td></tr><tr><td>Repairing misunderstanding</td><td>Ask for clarification, then restate shared understanding and open questions</td><td>The other person confirms accuracy and the next action did not change because of a guess;</td></tr></tbody></table><p>Do not use a speaking or writing score as a substitute when one of these is a high-risk part of the role. Keep the sample, audience feedback, and next parallel task together.</p><h2 id="_3-preserve-the-first-version-and-conditions" tabindex="-1">3. Preserve the First Version and Conditions <a class="header-anchor" href="#_3-preserve-the-first-version-and-conditions" aria-label="Permalink to &quot;3. Preserve the First Version and Conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>First-version location</th><th>Start/end</th><th>Tools and cues</th><th>Completed?</th><th>Main uncertainty</th></tr></thead><tbody><tr><td>Listening</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Reading</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Speaking</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Writing</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>What I can still explain independently:<br> Condition I would most like to change:<br> Conclusion this first version cannot support:</p><h2 id="_4-score-impact-not-feeling" tabindex="-1">4. Score Impact, Not Feeling <a class="header-anchor" href="#_4-score-impact-not-feeling" aria-label="Permalink to &quot;4. Score Impact, Not Feeling&quot;">​</a></h2><p>Score each <code>0-2</code>: <code>0=no evidence/not completed</code>, <code>1=partial, cue-dependent, or unstable</code>, <code>2=independent under current conditions</code>. Give every number an evidence location.</p><table tabindex="0"><thead><tr><th>Skill</th><th style="text-align:right;">Task completion</th><th style="text-align:right;">Comprehensibility</th><th style="text-align:right;">Accuracy/range</th><th style="text-align:right;">Organisation/fluency</th><th style="text-align:right;">Independence/transfer</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Listening</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Reading</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Speaking</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Writing</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><h3 id="scoring-meaning" tabindex="-1">Scoring Meaning <a class="header-anchor" href="#scoring-meaning" aria-label="Permalink to &quot;Scoring Meaning&quot;">​</a></h3><ul><li><strong>Task completion</strong>: did information and intention arrive, and can the action continue?</li><li><strong>Comprehensibility</strong>: could a real reader/listener understand without excessive guessing?</li><li><strong>Accuracy and range</strong>: did vocabulary, grammar, pronunciation, spelling, and detail support the task?</li><li><strong>Organisation/fluency</strong>: did structure, order, pauses, or layout obstruct use?</li><li><strong>Independence/transfer</strong>: can the task return after recent cues are removed and one condition changes?</li></ul><p>Use totals only for your own longitudinal comparison, never as a personality, intelligence, or hiring label. For CEFR direction, combine this with <a href="https://byoungd.github.io/up/en/threads/part-1/0-cefr" target="_blank" rel="noreferrer">CEFR Goals and Self-check</a> rather than turning one diagnostic into a permanent level.</p><h2 id="_5-choose-one-primary-barrier-per-skill" tabindex="-1">5. Choose One Primary Barrier per Skill <a class="header-anchor" href="#_5-choose-one-primary-barrier-per-skill" aria-label="Permalink to &quot;5. Choose One Primary Barrier per Skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Primary barrier</th><th>Sample/timestamp</th><th>Task impact</th><th>Smallest next repair</th><th>Evidence card</th></tr></thead><tbody><tr><td>Listening</td><td>vocabulary / sound / syntax / background / attention / device</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/en/templates/listening-audit" target="_blank" rel="noreferrer">Listening Evidence Card</a></td></tr><tr><td>Reading</td><td>vocabulary / structure / background / evidence / layout / capacity</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/en/templates/reading-evidence" target="_blank" rel="noreferrer">Reading Evidence Card</a></td></tr><tr><td>Speaking</td><td>chunks / pronunciation / organisation / interaction / register / follow-up</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/en/templates/speaking-evidence" target="_blank" rel="noreferrer">Speaking Evidence Card</a></td></tr><tr><td>Writing</td><td>task / fact / structure / sentence / register / delivery</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/en/templates/writing-evidence" target="_blank" rel="noreferrer">Writing Evidence Card</a></td></tr></tbody></table><p>If a barrier cannot be tied to a sample or timestamp, do not treat it as a conclusion yet. A learner may know many words and still fail to segment speech, or be accurate while unable to organise an asynchronous handover.</p><h2 id="_6-design-one-targeted-repair" tabindex="-1">6. Design One Targeted Repair <a class="header-anchor" href="#_6-design-one-targeted-repair" aria-label="Permalink to &quot;6. Design One Targeted Repair&quot;">​</a></h2><p>One barrier I will repair:<br> Repair action (25-45 minutes):<br> Material and source:<br> Minimum scaffold allowed:<br> Acceptance standard:<br> Before/after samples to preserve:<br> Feedback that would change the plan:</p><p>Usually protect meaning and task completion first, then facts and structure, then high-impact vocabulary, grammar, pronunciation, or register. Leave style details that do not change the result until later.</p><h2 id="_7-delayed-retest-and-transfer" tabindex="-1">7. Delayed Retest and Transfer <a class="header-anchor" href="#_7-delayed-retest-and-transfer" aria-label="Permalink to &quot;7. Delayed Retest and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Remove</th><th>Change</th><th>Output</th><th>Result/evidence</th></tr></thead><tbody><tr><td>Day 1</td><td>Answers after first version</td><td>Original conditions</td><td>Repair version</td><td></td></tr><tr><td>Day 7</td><td>Recent cues and old sentences</td><td>Parallel topic or audience</td><td>Same kind of task</td><td></td></tr><tr><td>Day 30</td><td>Tool conversation and comments</td><td>Real source or time pressure</td><td>One real delivery</td><td></td></tr><tr><td>Week 12</td><td>Old task and score</td><td>Target role, course, or life context</td><td>Complete task</td><td></td></tr></tbody></table><p>What I can still do independently on day 7:<br> Error that still returns on day 30:<br> Skill that succeeded only on a familiar topic:<br> Where extra time would most affect life:<br> What this retest cannot prove:</p><h2 id="_8-record-ai-translation-and-human-feedback" tabindex="-1">8. Record AI, Translation, and Human Feedback <a class="header-anchor" href="#_8-record-ai-translation-and-human-feedback" aria-label="Permalink to &quot;8. Record AI, Translation, and Human Feedback&quot;">​</a></h2><p>Tool / model / version and date:<br> Samples that existed before tool use:<br> What it did: diagnosis / questions / counterexample / transcript / feedback / other<br> Scope generated or rewritten:<br> Primary source, dictionary, teacher, peer, or real-audience check:<br> Suggestions accepted, rejected, or deferred and why:<br> Independent sample after closing the tool:<br> Disclosure required by school, client, employer, or exam:</p><p>Model answers, speech-recognition scores, and polished final prose cannot independently prove ability. Important judgments return to original material, actual response, and a named accountable owner.</p><h2 id="_9-decide-the-next-cycle" tabindex="-1">9. Decide the Next Cycle <a class="header-anchor" href="#_9-decide-the-next-cycle" aria-label="Permalink to &quot;9. Decide the Next Cycle&quot;">​</a></h2><p>Current component direction (not a permanent level):<br> Strongest real evidence:<br> Weakest evidence with the largest life impact:<br> Continue:<br> Downgrade:<br> Change variable:<br> Pause or seek help:<br> Smallest next task:<br> Next review date:</p><p>Related entry points: <a href="https://byoungd.github.io/up/en/threads/part-1/1-understanding" target="_blank" rel="noreferrer">Learning Principles: Turn Effort into Verifiable Learning</a> | <a href="https://byoungd.github.io/up/en/templates/vocabulary-audit" target="_blank" rel="noreferrer">Vocabulary Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/grammar-evidence" target="_blank" rel="noreferrer">Grammar Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/listening-audit" target="_blank" rel="noreferrer">Listening Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/reading-evidence" target="_blank" rel="noreferrer">Reading Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/speaking-evidence" target="_blank" rel="noreferrer">Speaking Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/writing-evidence" target="_blank" rel="noreferrer">Writing Evidence Card</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/english-diagnostic" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-10-19. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',41)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
